          '**Ce test n\'a pas fait l\'objet d\'un essai pratique par PromptQuorum sur un exemplaire physique.** Il s\'appuie sur les spécifications publiées par le fabricant et sur des tests indépendants tiers, clairement séparés ci-dessous pour distinguer ce qui est confirmé de ce qui est estimé.',
