        content:
          '**PromptQuorum no ha probado este análisis de forma práctica sobre una unidad física.** Está construido a partir de especificaciones publicadas por el fabricante y análisis independientes de terceros, separados con claridad abajo para que sepas qué está confirmado y qué está estimado.',
