      faqSection: {
        id: 'faq',
        title: 'Preguntas frecuentes',
        faqs: [
          { q: '¿Es bueno el GMKtec G3 Plus para Home Assistant?', a: 'Sí. Ejecuta Home Assistant y complementos habituales (Zigbee2MQTT, Node-RED, AdGuard) con comodidad y bajo consumo en reposo. Su único puerto 2.5GbE lo hace menos apto como caja de red que el Beelink EQ14, con doble LAN.' },
          { q: '¿Puede el GMKtec G3 Plus ejecutar Ollama?', a: 'Sí. Ollama se instala y funciona con normalidad en el G3 Plus; un modelo de 1B–4B responde bien, y los modelos de 7–8B funcionan pero van lentos. Esto está estimado a partir de su hardware verificado, no es un benchmark fijo.' },
          { q: '¿Puede el GMKtec G3 Plus ejecutar modelos Llama o Qwen?', a: 'Sí, en la gama pequeña. Un modelo Llama o Qwen de 1B–4B con cuantización de 4-bit funciona con comodidad; una variante de 7–8B es usable pero lenta por el ancho de banda DDR4 de un solo canal y el N150 de cuatro núcleos.' },
          { q: '¿Puede el G3 Plus ejecutar un modelo de 7B?', a: 'Entra y funciona, pero lento — cuenta con que sea usable para tareas no interactivas (resúmenes, trabajos por lotes) más que para un chat ágil de ida y vuelta. Para un asistente 7B con buena respuesta, una caja Ryzen como el Beelink SER8 es mejor opción.' },
          { q: '¿Cuánta RAM admite el G3 Plus?', a: 'Hasta 32 GB mediante un único SO-DIMM DDR4-3200. GMKtec lo envía preconfigurado con 8 GB o 16 GB — no existe una versión de fábrica con 32 GB, así que llegar a 32 GB significa comprar e instalar el módulo tú mismo.' },
          { q: '¿La RAM del G3 Plus es ampliable, o está soldada?', a: 'Ampliable. El G3 Plus usa una sola ranura SO-DIMM DDR4 reemplazable, no memoria soldada. Esa es una ventaja real frente a las cajas económicas con RAM fija — aunque en agosto de 2026 un SO-DIMM DDR4-3200 de 32 GB ronda los 250 € en España por la escasez del mercado de memoria, así que comprueba el precio de la ampliación antes de asumir que es barata.' },
          { q: '¿Puedo instalar 32 GB de RAM yo mismo?', a: 'Sí — es un cambio de SO-DIMM estándar. Compra un único módulo SO-DIMM DDR4-3200 de 32 GB (la ranura es de un solo canal, así que con un módulo basta) y sustituye el que trae de serie.' },
          { q: '¿Tiene el G3 Plus un puerto USB-C?', a: 'No. Este modelo tiene cuatro puertos USB-A y dos salidas HDMI pero ningún puerto USB-C. El Beelink EQ14, en cambio, tiene un puerto USB-C (10 Gbps, solo datos).' },
          { q: '¿Tiene el G3 Plus doble LAN?', a: 'No — tiene un solo puerto 2.5GbE. El Beelink EQ14 tiene dos puertos 2.5GbE, lo que lo convierte en mejor opción si quieres que el mini PC también haga tareas de red.' },
          { q: '¿Puede el G3 Plus ejecutar Frigate?', a: 'Puede, pero la detección solo con CPU y sin NPU lo limita a un número pequeño de cámaras con resolución/fotogramas modestos. Es posible, no ideal — una caja Ryzen con una iGPU más potente maneja Frigate con más comodidad.' },
          { q: '¿Es el GMKtec G3 Plus mejor que el Beelink EQ14?', a: 'Ninguno es estrictamente mejor — cada uno cede en un punto distinto. El G3 Plus gana en techo de RAM (32 GB frente a 16 GB); el EQ14 gana en red (2.5GbE doble, más un puerto USB-C). Elige según qué compromiso te importa más para tu instalación.' },
          { q: '¿GMKtec G3 Plus o Raspberry Pi 5 para Home Assistant?', a: 'El G3 Plus tiene mucho más margen de RAM, compatibilidad x86 y espacio para añadir un LLM local — la Pi 5 es más barata y pequeña pero mucho más limitada en RAM y CPU para cualquier cosa que vaya más allá de Home Assistant en sí.' },
          { q: '¿Es el G3 Plus bueno para funcionamiento 24/7?', a: 'Sí. Con unos 6 W en reposo es barato dejarlo funcionando de forma continua, y los análisis independientes reportan una térmica moderada bajo carga ligera sostenida. No hay datos de durabilidad a largo plazo, ya que PromptQuorum no ha tenido ninguna unidad funcionando de forma continua.' },
          { q: '¿Cuánta electricidad consume el G3 Plus?', a: 'Unos 6 W en reposo y unos 21–26 W en carga. Dejado mayormente en reposo durante un año completo, eso equivale a unos 52.6 kWh — una adición pequeña y predecible a la factura eléctrica de casa, sea cual sea la tarifa local.' },
          { q: '¿Merece la pena comprar el GMKtec G3 Plus en 2026?', a: 'Para su cometido declarado — un concentrador Home Assistant barato y de bajo consumo con margen para probar un modelo local pequeño — sí. Para quien de verdad quiera IA local rápida, no; ese presupuesto está mejor invertido en una caja Ryzen como el Beelink SER8.' },
          { q: '¿Dónde se fabrica el GMKtec G3 Plus, y afecta eso al precio?', a: 'Se fabrica en China. En 2026, las medidas de importación de EE. UU. (aranceles de la Sección 301, el fin de la exención de minimis por debajo de 800 $) y la eliminación por la UE de la exención de 150 € para paquetes de bajo valor pueden afectar al coste final, así que consulta el precio actual del vendedor en lugar de fiarte de una cifra fija.' },
        ],
      },
